diff --git a/server/tests/isread_behavior.test.js b/server/tests/isread_behavior.test.js
new file mode 100644
index 0000000..524f0c6
--- /dev/null
+++ b/server/tests/isread_behavior.test.js
@@ -0,0 +1,150 @@
+'use strict';
+/**
+ * Behavioral tests for the isRead boolean filter in getAllEmails.
+ * Verifies the controller handles boolean isRead (post-Joi coercion) correctly.
+ */
+
+// Jest hoists jest.mock() calls before all requires/variable declarations.
+// Use __dirname directly - it IS available in the hoisted scope.
+
+jest.mock(__dirname + '/../src/queues/index.js', () => ({
+    queues: {},
+    addEmailToProcessing: async () => {},
+}));
+
+jest.mock(__dirname + '/../src/utils/logger.js', () => ({
+    info() {}, error() {}, warn() {}, debug() {},
+}));
+
+jest.mock(__dirname + '/../src/utils/searchMonitor.js', () => ({
+    recordSearch() {},
+}));
+
+jest.mock(__dirname + '/../src/config/redis.js', () => ({
+    connection: {},
+}));
+
+jest.mock(__dirname + '/../src/models/user.model.js', () => ({}));
+jest.mock(__dirname + '/../src/modules/threads/thread.model.js', () => ({}));
+jest.mock(__dirname + '/../src/modules/audit/audit.model.js', () => ({}));
+jest.mock(__dirname + '/../src/modules/modifications/modification.model.js', () => ({}));
+jest.mock(__dirname + '/../src/modules/attachments/attachment.model.js', () => ({}));
+
+jest.mock(__dirname + '/../src/services/search.service.js', () => ({
+    buildSearchFilters(params) {
+        const f = {};
+        if (params.accountId) f.accountId = params.accountId;
+        if (params.status) f.status = params.status;
+        return f;
+    },
+    async searchEmails({ filters, page, limit }) {
+        const emails = require(__dirname + '/isread_behavior.test.js').__TEST_EMAILS;
+        function filter(q) {
+            return emails.filter(e => Object.entries(q || {}).every(([k, v]) => String(e[k]) === String(v)));
+        }
+        const filtered = filter(filters);
+        const skip = (page - 1) * limit;
+        return { success: true, data: filtered.slice(skip, skip + limit), pagination: { total: filtered.length, page, limit, pages: Math.ceil(filtered.length / limit) } };
+    }
+}));
+
+jest.mock(__dirname + '/../src/models/email.model.js', () => {
+    function filter(emails, query = {}) {
+        return emails.filter(email =>
+            Object.entries(query).every(([k, v]) => {
+                if (v !== null && typeof v === 'object' && !Array.isArray(v)) {
+                    if ('$in' in v) return v.$in.some(x => String(email[k]) === String(x));
+                }
+                return String(email[k]) === String(v);
+            })
+        );
+    }
+    const EMAILS = [
+        { _id: '507f1f77bcf86cd799439011', accountId: 'acc1', status: 'NEW', category: 'Issue', priority: 'HIGH', isRead: true,  subject: 'Read email one',   createdAt: new Date('2026-01-03T10:00:00Z') },
+        { _id: '507f1f77bcf86cd799439012', accountId: 'acc1', status: 'NEW', category: 'Issue', priority: 'LOW',  isRead: false, subject: 'Unread email one', createdAt: new Date('2026-01-02T10:00:00Z') },
+        { _id: '507f1f77bcf86cd799439013', accountId: 'acc1', status: 'NEW', category: 'Issue', priority: 'LOW',  isRead: false, subject: 'Unread email two', createdAt: new Date('2026-01-01T10:00:00Z') },
+    ];
+    return {
+        find(query) {
+            const filtered = filter(EMAILS, query);
+            const state = { filtered, skipCount: 0, limitCount: filtered.length };
+            return {
+                sort() { return this; },
+                skip(n) { state.skipCount = n; return this; },
+                limit(n) { state.limitCount = n; return this; },
+                populate() { return this; },
+                lean() { return Promise.resolve(state.filtered.slice(state.skipCount, state.skipCount + state.limitCount)); }
+            };
+        },
+        countDocuments(query) { return Promise.resolve(filter(EMAILS, query).length); },
+        aggregate(pipeline) {
+            const scoped = filter(EMAILS, pipeline[0]?.$match);
+            const gf = pipeline[1]?.$group?._id?.replace('$', '');
+            const counts = {};
+            for (const e of scoped) { const v = e[gf]; if (v !== undefined) counts[v] = (counts[v] || 0) + 1; }
+            return Promise.resolve(Object.entries(counts).map(([_id, count]) => ({ _id, count })));
+        },
+        schema: { path: () => ({}) },
+    };
+});
+
+// ─── Load controller (mocks are already registered above) ──────────────────
+const emailController = require('../src/controllers/email.controller.js');
+
+// ─── Helpers ───────────────────────────────────────────────────────────────
+function makeRes() {
+    return {
+        statusCode: 200, body: null,
+        status(c) { this.statusCode = c; return this; },
+        json(p) { this.body = p; return this; },
+    };
+}
+function makeNext() {
+    const s = { error: null };
+    const fn = (e) => { s.error = e || null; };
+    fn.state = s;
+    return fn;
+}
+
+// ─── Tests ─────────────────────────────────────────────────────────────────
+describe('isRead boolean filter', () => {
+
+    test('isRead boolean filter correctly returns only read emails when isRead is true', async () => {
+        const req = { query: { isRead: true, page: 1, limit: 10, sortBy: 'createdAt', sortOrder: 'desc' } };
+        const res = makeRes();
+        const next = makeNext();
+
+        await emailController.getAllEmails(req, res, next);
+
+        expect(next.state.error).toBeNull();
+        expect(res.statusCode).toBe(200);
+        expect(res.body.pagination.total).toBe(1);
+        expect(res.body.data[0].subject).toBe('Read email one');
+    });
+
+    test('isRead boolean filter correctly returns only unread emails when isRead is false', async () => {
+        const req = { query: { isRead: false, page: 1, limit: 10, sortBy: 'createdAt', sortOrder: 'desc' } };
+        const res = makeRes();
+        const next = makeNext();
+
+        await emailController.getAllEmails(req, res, next);
+
+        expect(next.state.error).toBeNull();
+        expect(res.statusCode).toBe(200);
+        expect(res.body.pagination.total).toBe(2);
+        expect(res.body.data.every(e => e.subject.startsWith('Unread'))).toBe(true);
+    });
+
+    test('omitting isRead returns all emails regardless of read status', async () => {
+        const req = { query: { page: 1, limit: 10, sortBy: 'createdAt', sortOrder: 'desc' } };
+        const res = makeRes();
+        const next = makeNext();
+
+        await emailController.getAllEmails(req, res, next);
+
+        expect(next.state.error).toBeNull();
+        expect(res.statusCode).toBe(200);
+        expect(res.body.pagination.total).toBe(3);
+    });
+
+});
